mapper.select:
SELECT p.id, p.author_id, p.content, p.title, p.image_urls, p.video_id, p.is_pinned, p.like_count, p.comment_count, p.share_count, p.created_at, u.nickname AS author_nickname, u.avatar_url AS author_avatar, u.signature AS author_signature, v.title AS video_title, v.cover_url AS video_cover, v.duration_seconds AS video_duration, EXISTS (SELECT 1 FROM post_like r WHERE r.user_id = #{viewerId} AND r.post_id = p.id) AS liked, EXISTS(SELECT 1 FROM watch_later wl WHERE wl.video_id = p.video_id AND wl.user_id = #{viewerId}) AS watch_later FROM user_post p JOIN `user` u ON u.id = p.author_id AND u.deleted_at IS NULL LEFT JOIN video v ON v.id = p.video_id AND v.deleted_at IS NULL WHERE p.status = 1 AND p.deleted_at IS NULL AND (p.visibility = 0 OR p.author_id = #{viewerId})
AND p.author_id = #{targetUserId}
AND p.id < #{cursorId}
ORDER BY p.id DESC LIMIT #{limit}

SELECT p.id, p.author_id, p.content, p.title, p.image_urls, v.id AS video_id, p.is_pinned, p.like_count, p.comment_count, p.share_count, p.created_at, u.nickname AS author_nickname, u.avatar_url AS author_avatar, u.signature AS author_signature, v.title AS video_title, v.cover_url AS video_cover, v.duration_seconds AS video_duration, EXISTS(SELECT 1 FROM post_like l WHERE l.post_id=p.id AND l.user_id=#{viewerId}) AS liked, EXISTS(SELECT 1 FROM watch_later w WHERE w.video_id=p.video_id AND w.user_id=#{viewerId}) AS watch_later FROM user_post p JOIN `user` u ON u.id=p.author_id AND u.deleted_at IS NULL LEFT JOIN video v ON v.id=p.video_id AND v.status=1 AND v.deleted_at IS NULL WHERE p.status=1 AND p.deleted_at IS NULL AND (p.visibility=0 OR p.author_id=#{viewerId}) AND p.author_id=#{targetUserId}
AND (p.author_id=#{viewerId} OR EXISTS( SELECT 1 FROM user_follow f WHERE f.follower_id=#{viewerId} AND f.followee_id=p.author_id))
AND p.video_id IS NOT NULL AND p.video_id IS NULL
AND (p.is_pinned < COALESCE((SELECT is_pinned FROM user_post WHERE id=#{cursorId}),0) OR (p.is_pinned=COALESCE((SELECT is_pinned FROM user_post WHERE id=#{cursorId}),0) AND p.id < #{cursorId}))
AND p.id < #{cursorId}
ORDER BY p.is_pinned DESC, p.id DESC LIMIT #{limit}

SELECT u.id AS user_id,u.id AS relation_id,u.nickname,u.avatar_url,u.level,u.signature,
       COALESCE(s.follower_count,0) AS follower_count, f.id IS NOT NULL AS followed
FROM `user` u
LEFT JOIN user_stats s ON s.user_id=u.id
LEFT JOIN user_follow f ON f.follower_id=#{viewerId} AND f.followee_id=u.id
WHERE u.deleted_at IS NULL AND u.status=1 AND u.id != #{viewerId}
AND u.id < #{cursorId}
ORDER BY u.id DESC LIMIT #{limit}

SELECT u.id AS user_id,f.id AS relation_id,u.nickname,u.avatar_url,u.level,TRUE AS followed,
       (SELECT COUNT(*) FROM user_post p WHERE p.author_id=u.id AND p.status=1
          AND p.deleted_at IS NULL AND p.visibility=0
          AND p.created_at > COALESCE(f.last_seen_post_at,f.created_at)) AS unread_count
FROM user_follow f JOIN `user` u ON u.id=f.followee_id AND u.deleted_at IS NULL
WHERE f.follower_id=#{viewerId}
AND f.id < #{cursorId}
ORDER BY f.id DESC LIMIT #{limit}

SELECT u.id AS user_id, f.id AS relation_id, u.nickname, u.avatar_url, u.signature, u.level, f.created_at AS followed_at, CASE WHEN EXISTS (SELECT 1 FROM user_follow ff WHERE ff.follower_id = #{viewerId} AND ff.followee_id = u.id) THEN TRUE ELSE FALSE END AS followed FROM user_follow f JOIN `user` u ON u.id = f.follower_id f.followee_id AND u.deleted_at IS NULL WHERE 1 = 1
AND f.followee_id = #{otherId} AND f.follower_id = #{viewerId}
AND f.id < #{cursorId}
ORDER BY f.id DESC LIMIT #{limit}
